input.command:
cd "$ARCHON_HORIZON_ROOT" && echo "=== dat-j.properness-substrate node ===" && "$HORIZON_BIN" roadmap show AJCR.w4-rep.datum.dat-j.properness-substrate 2>/dev/null | head -40
echo "=== which ingredients exist in AJCR? ==="
for name in "HasFiniteMapToP1" "p1LaurentChartData" "isProjective_of_finiteMap" "IsProjectiveWith" "SmoothOfRelativeDimension" "NonconstantToP1" "geometricallyIntegral"; do
  n=$("$HORIZON_BIN" search "$name" --project Algebraic-Jacobian-Challenge-Rebuild --json 2>/dev/null | python3 -c "import sys,json; 
try:
 d=json.load(sys.stdin); r=d.get('results',d) if isinstance(d,dict) else d; print(len(r))
except: print('ERR')" 2>/dev/null)
  echo "$name : AJCR hits=$n"
done
